parameters.jsCode:
// Turns whatever the visitor typed into a proper web address, refuses anything
// that isn't a public website, and keeps a daily count so the widget can't be abused.
// (Plain pattern matching, because the Code node has no built-in URL parser.)
const body = $input.first().json.body || {};
const raw = String(body.url || '').trim().slice(0, 300);
const m = raw.match(/^(?:(https?):\/\/)?([a-z0-9.-]+)(:\d+)?([\/?#]\S*)?$/i);
const host = m ? m[2].toLowerCase() : '';
const notPublic = !m || !!m[3] || !host.includes('.') || host.startsWith('.') || host.endsWith('.') ||
  host === 'localhost' || host.endsWith('.local') || host.endsWith('.internal') ||
  /^\d{1,3}(\.\d{1,3}){3}$/.test(host);
const url = notPublic ? '' : ((m[1] || 'https').toLowerCase() + '://' + host + (m[4] || '/'));

const LIMIT = 100;
const store = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
if (store.day !== today) { store.day = today; store.count = 0; }

let error = '';
if (!url) error = 'invalid_url';
else if (store.count >= LIMIT) error = 'daily_limit';
else store.count += 1;

return [{ json: { ok: !error, error, url } }];

// Pulls the readable parts out of the page: title, description, headings and body text.
// Scripts, styles and tags are stripped, and the text is capped so the AI stays fast.
const html = String($input.first().json.data || '').slice(0, 600000);
const pick = (re) => (html.match(re) || [])[1] || '';
const clean = (s) => String(s)
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&(#39|rsquo|lsquo);/g, "'")
  .replace(/&quot;/g, '"').replace(/&[a-z0-9#]+;/gi, ' ')
  .replace(/\s+/g, ' ').trim();

const title = clean(pick(/<title[^>]*>([\s\S]*?)<\/title>/i));
const description = clean(
  pick(/<meta[^>]+name=["']description["'][^>]*content=["']([^"']*)/i) ||
  pick(/<meta[^>]+property=["']og:description["'][^>]*content=["']([^"']*)/i)
);
const headings = [...html.matchAll(/<h[1-3][^>]*>([\s\S]*?)<\/h[1-3]>/gi)]
  .map((m) => clean(m[1])).filter(Boolean).slice(0, 15);
const bodyText = clean(pick(/<body[^>]*>([\s\S]*)<\/body>/i) || html).slice(0, 3500);

return [{ json: {
  url: $('Check URL and Daily Limit').first().json.url,
  title, description, headings, body: bodyText,
} }];

// Firecrawl renders JavaScript, so it can read sites the plain fetch couldn't.
// If Firecrawl also fails, whatever the plain fetch found is kept.
const d = ($input.first().json || {}).data || {};
let prev = {};
try { prev = $('Extract Page Text').first().json; } catch (e) {}
const md = String(d.markdown || '')
  .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
  .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
  .replace(/[#*_>|]+/g, ' ')
  .replace(/\s+/g, ' ').trim();
const meta = d.metadata || {};

return [{ json: {
  url: $('Check URL and Daily Limit').first().json.url,
  title: meta.title || prev.title || '',
  description: meta.description || meta.ogDescription || prev.description || '',
  headings: prev.headings || [],
  body: (md || prev.body || '').slice(0, 3500),
} }];

