parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "business": {
      "type": "string",
      "description": "One sentence, under 25 words: what this business does and who it serves, based only on the page."
    },
    "ideas": {
      "type": "array",
      "minItems": 3,
      "maxItems": 3,
      "items": {
        "type": "object",
        "properties": {
          "title": {
            "type": "string",
            "description": "Name of the automation, 2 to 6 words."
          },
          "how": {
            "type": "string",
            "description": "One sentence, under 30 words, saying exactly what the automation does for THIS business."
          },
          "impact": {
            "type": "string",
            "description": "Under 10 words: the benefit in plain words. No invented statistics."
          }
        },
        "required": [
          "title",
          "how",
          "impact"
        ]
      }
    }
  },
  "required": [
    "business",
    "ideas"
  ]
}
